const company = $('Loop Over Items').item.json;

return [{
  json: {
    name: company.name,
    careers_url: company.careers_url,
    ats: company.ats,
    ats_token: company.ats_token,
    github_org: company.github_org,
    github: {
      repos: $input.all().map(item => ({
        name: item.json.name,
        updated_at: item.json.updated_at,
        pushed_at: item.json.pushed_at,
        stars: item.json.stargazers_count,
        forks: item.json.forks_count,
        description: item.json.description
      }))
    }
  }
}];

const company = $('Loop Over Items').item.json;
const articles = ($input.first().json.articles) || [];

return [{
  json: {
    name: company.name,
    careers_url: company.careers_url,
    ats: company.ats,
    ats_token: company.ats_token,
    github_org: company.github_org,
    news: {
      articles: articles.map(a => ({
        title: a.title,
        source: a.source?.name,
        published_at: a.publishedAt,
        url: a.url,
        description: a.description
      }))
    }
  }
}];

const data = $input.first().json;
const prompt = `Analyze the following public signals for ${data.company} and score their demand potential from 0-100 based on evidence that they are actively building or scaling their go-to-market motion.
High-weight signals:
- Hiring for GTM, sales, RevOps, or marketing roles
- Recent funding round (more budget, more tooling)
- New sales or marketing leadership (new leaders buy new tools)
- Product launches suggesting commercial expansion
- Rapid headcount growth signals
Low-weight signals:
- General press coverage unrelated to commercial motion
- Pure engineering activity with no GTM relevance
GitHub Activity:
${JSON.stringify(data.signals.github)}
Recent News:
${JSON.stringify(data.signals.news)}
Job Postings (GTM roles only):
${JSON.stringify(data.signals.jobs)}
Return JSON only, no other text, in this exact format:
{
  "company_summary": "2-3 sentence snapshot based only on signals provided",
  "intent_score": 0,
  "tier": "high or medium or low",
  "score_reasons": ["reason 1", "reason 2"],
  "key_signals": ["signal 1", "signal 2"],
  "missing_signals": ["what would strengthen this score"]
}`;
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': '<ANTHROPIC_API_KEY>',
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-sonnet-4-6',
    max_tokens: 1000,
    system: 'You are a senior sales intelligence analyst at an enterprise B2B GTM software company. Your job is to assess how likely a prospect company is to be actively in-market for GTM software. Base your analysis strictly on the signals provided. Do not use prior knowledge about the company beyond what is present in the data.',
    messages: [{ role: 'user', content: prompt }]
  })
});
const content = response.content[0].text;
const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const parsed = JSON.parse(cleaned);
return [{
  json: {
    company: data.company,
    careers_url: data.careers_url,
    github_org: data.github_org,
    signals: data.signals,
    scoring: parsed
  }
}];

const company = $('Loop Over Items').item.json;
const data = $input.first().json || {};

let rawJobs = [];
let source = 'none';

if (Array.isArray(data.jobs)) {
  source = 'greenhouse';
  rawJobs = data.jobs.map(j => ({
    title: j.title,
    location: j.location?.name,
    posted_at: j.first_published,
    url: j.absolute_url
  }));
} else if (Array.isArray(data.jobPostings)) {
  source = 'ashby';
  rawJobs = data.jobPostings.map(j => ({
    title: j.title,
    location: j.location,
    posted_at: j.publishedAt,
    url: j.jobUrl
  }));
}

return [{
  json: {
    name: company.name,
    careers_url: company.careers_url,
    ats: company.ats,
    ats_token: company.ats_token,
    github_org: company.github_org,
    jobs: { source, raw: rawJobs }
  }
}];

const input = $input.first().json;

const gtmKeywords = ['sales','marketing','revenue','gtm','go-to-market','account executive','account manager','business development','demand generation','growth','partnerships','customer success','revops','sales ops','marketing ops'];

const allJobs = input.jobs?.raw || [];
const gtmJobs = allJobs.filter(j => {
  const t = (j.title || '').toLowerCase();
  return gtmKeywords.some(k => t.includes(k));
});

return [{
  json: {
    company: input.name,
    careers_url: input.careers_url,
    github_org: input.github_org,
    signals: {
      news: input.news?.articles || [],
      github: input.github?.repos || [],
      jobs: {
        source: input.jobs?.source || 'none',
        gtm_job_count: gtmJobs.length,
        total_job_count: allJobs.length,
        gtm_jobs: gtmJobs.slice(0, 10)
      }
    }
  }
}];

const results = $input.all().map(item => item.json);

const sorted = results.sort((a, b) => 
  (b.scoring?.intent_score || 0) - (a.scoring?.intent_score || 0)
);

const runId = new Date().toISOString();

const formatList = (arr) => Array.isArray(arr) 
  ? arr.map((item, i) => `${i + 1}. ${item}`).join('\n')
  : '';

return sorted.map((c, i) => ({
  json: {
    run_id: runId,
    rank: i + 1,
    company: c.company,
    intent_score: c.scoring?.intent_score ?? 0,
    tier: c.scoring?.tier || '',
    company_summary: c.scoring?.company_summary || '',
    score_reasons: formatList(c.scoring?.score_reasons),
    key_signals: formatList(c.scoring?.key_signals),
    missing_signals: formatList(c.scoring?.missing_signals),
    gtm_job_count: c.signals?.jobs?.gtm_job_count ?? 0,
    total_job_count: c.signals?.jobs?.total_job_count ?? 0,
    news_article_count: Array.isArray(c.signals?.news) ? c.signals.news.length : 0,
    github_repo_count: Array.isArray(c.signals?.github) ? c.signals.github.length : 0,
    careers_url: c.careers_url || '',
    github_org: c.github_org || ''
  }
}));

const data = $getWorkflowStaticData('global');  // 'global' not 'node'
if (!data.results) data.results = [];

data.results.push($input.first().json);

return $input.all();
